---IsValidAccount 用户名是否合法
---@param username string
---@param startL number
---@param endL number
local function IsValidAccount(username, startL, endL)
    if not Utils.IsLengthRange(username, startL, endL) then
        return localize('账号长度不符合要求')
    else
        if not Regex.IsMatch(username, '^[a-zA-Z0-9\\.@]') then
            return localize("账号格式不正确")
        end
    end
end

local function IsValidPassword(password, startL, endL)
    printInfo(Utils.IsLengthRange(password, startL, endL))
    if not Utils.IsLengthRange(password, startL, endL) then
        return localize('密码长度不符合要求')
    else
        if not Regex.IsMatch(password, '^[a-zA-Z0-9\\.@]') then
            return localize("密码格式不正确")
        end
    end
end

