function LoginPanelMB:Awake()
    local loginBtn = self.LoginBtn:GetComponent(typeof(Button))
    local registerBtn = self.RegistBtn:GetComponent(typeof(Button))
    SetButtonAction(loginBtn, Bind(self, self.OnLoginInAction))
    SetButtonAction(registerBtn, Bind(self, self.OnRegisterAction))
end

function LoginPanelMB:Start()
    self:LoadPassword()
end

function LoginPanelMB:LoadPassword()
    --是否显示上次登录的账号密码
    if Config.DEBUG then
        local nameTextField = self.UserNameInput:Find("InputField")
        local passwordTextField = self.PasswordInput:Find("InputField")
        local storeValue = CS.Engine.Tools.PlayerPrefsUtility.GetEncryptedString(Config.LastLoginUserPasswordPreferenceKey)
        if not string.isEmpty(storeValue) then
            local t = table.deserialize(storeValue)
            nameTextField:GetComponent(typeof(InputField)).text = checkString(t.username)
            passwordTextField:GetComponent(typeof(InputField)).text = checkString(t.password)
        end
    end
end

function LoginPanelMB:OnLoginInAction()
    ---@type UnityEngine.UI.InputField
    local nameTextField = self.UserNameInput:Find("InputField")
    local passwordTextField = self.PasswordInput:Find("InputField")
    local username = nameTextField:GetComponent(typeof(InputField)).text
    local password = passwordTextField:GetComponent(typeof(InputField)).text

    local errorMsg = IsValidAccount(username, 4, 13)
    if not string.isEmpty(errorMsg) then
        self:ShakeError(errorMsg)
        return
    end
    errorMsg = IsValidPassword(password, 5, 13)
    if not string.isEmpty(errorMsg) then
        self:ShakeError(errorMsg)
        return
    end
    CS.Engine.Http.HttpModule.RequestBodyMeta.PlayerId = ""
    CS.Engine.Http.HttpModule.RequestBodyMeta.UserId = ""
    xRecord.setUserPlayer({userId = ""})
    xRecord.setUserPlayer({ playerId = "" })
    gameUtils.Request(Interfaces.UserLogin, { uname = username, password = password },
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local data = checkTable(response.data)
                    ---@type ECSWorldMgr
                    local worldMgr = ECSWorldMgr:GetInstance()
                    ---@type ECSWorld
                    local world = worldMgr:GetWorld(Constants.GameWorld)
                    ---@type ECSEntity
                    local entity = world:GetEntity(Constants.PlayerEntityId)
                    entity:RemoveComp(ECSComponentType.Constants.UserComponent)
                    ---@type UserComponent
                    local userComp = entity:GetOrAddComp(ECSComponentType.Constants.UserComponent)
                    userComp:Initial(data)
                    local SDKService = import("Game.Entry.SDKService")
                    SDKService:GetInstance():SetIsLogin(true)
                    Events.Broadcast(Constants.EventNames.ChangeAuthenticationValue, userComp:GetRealAuthenticationInfo())
                    KTool.SetActive(self.controller.gameObject, false)
                    KTool.SetActive(self.RegistPanel.gameObject, false)
                    KTool.SetActive(self.StartGamePanel.gameObject, true)
                    local lastLoginServerId = checkInt(userComp.userInfo.lastLoginServerId)
                    if lastLoginServerId > 0 then
                        local HttpModule = CS.Engine.Http.HttpModule
                        HttpModule.RequestBodyMeta.serverId = tostring(lastLoginServerId)
                         ---@type UserComponent
                        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                        if isNotNull(userComponent) then
                            userComponent:SetRequestBodyMetaServerAreaId()
                        end
                    end 
                    if Config.WriteAccount then
                        local str = table.serialize({ username = username, password = password })
                        CS.Engine.Tools.PlayerPrefsUtility.SetEncryptedString(Config.LastLoginUserPasswordPreferenceKey, str)
                    end
                    Events.Broadcast(Constants.EventNames.UIGameInitEvent)
                    Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_LOGIN, data = data })
                --else
                --    self:ShakeError(response.errMsg)
                end
            end, function(exception)
                self:ShakeError(exception.Message)
            end)
end

---RegisterAction
---按钮事件，点击到注册页面
