function LoginPanelMB:OnRegisterAction()
    KTool.SetActive(self.RegistPanel.gameObject, true)
    KTool.SetActive(self.LoginPanel.gameObject, false)
end

function LoginPanelMB:OnDestroy()
    self.GameInit = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return LoginPanelMB